students_map = {s['name']: s['id'] for s in json.loads(students_json)}
classes_map = {c['name']: c['id'] for c in json.loads(classes_json)}

# enrollment 생성
enrollments = []
not_found_students = set()
not_found_classes = set()

for _, row in df_active.iterrows():
    student_name = row['이름']
    class_name = row['수업명']

    if student_name not in students_map:
        not_found_students.add(student_name)
        continue
    if class_name not in classes_map:
        not_found_classes.add(class_name)
        continue

    student_id = students_map[student_name]
    class_id = classes_map[class_name]
    enrollments.append((student_id, class_id))

# 중복 제거
enrollments = list(set(enrollments))

print(f"총 enrollment 수: {len(enrollments)}")
print(f"찾지 못한 학생: {len(not_found_students)}")
print(f"찾지 못한 수업: {len(not_found_classes)}")

if not_found_students:
    print("\n찾지 못한 학생 목록:")
    for name in sorted(not_found_students):
        print(f"  - {name}")

if not_found_classes:
    print("\n찾지 못한 수업 목록:")
    for name in sorted(not_found_classes):
        print(f"  - {name}")

# SQL INSERT 문 생성 (배치로 나눠서)
print("\n\n-- SQL INSERT 문 --")
batch_size = 50
for i in range(0, len(enrollments), batch_size):
    batch = enrollments[i:i+batch_size]
    values = ",\n".join([f"('{sid}', '{cid}')" for sid, cid in batch])
    print(f"\n-- Batch {i//batch_size + 1}")
    print(f"INSERT INTO enrollments (student_id, class_id) VALUES\n{values};")
